mapper.sql:
WITH sales_base AS ( SELECT f.store_no AS storeNo, MAX(f.store_name) AS storeName, ISNULL(SUM(CAST(f.sale_quantity AS DECIMAL(20, 6))), 0) AS saleQuantity, ISNULL(SUM(CAST(f.sales AS DECIMAL(20, 6))), 0) AS sales, ISNULL(SUM(CAST(f.gross AS DECIMAL(20, 6))), 0) AS gross, ISNULL(SUM(CAST(f.sale_cost AS DECIMAL(20, 6))), 0) AS saleCost, CASE WHEN MAX(CASE WHEN ISNULL(LTRIM(RTRIM(f.cx_flag)), '0') IN ('1', 'Y', 'y', 'true', 'TRUE') THEN 1 ELSE 0 END) = 1 THEN N'是' ELSE N'否' END AS activity, MIN(f.sale_date) AS firstSaleDate FROM fact_sales_day f WHERE f.sale_date >= #{param.periodStart} AND f.sale_date <= #{param.periodEnd} AND f.product_no = #{productNo} AND f.sales > 0
GROUP BY f.store_no ), stock_base AS ( SELECT s.store_no AS storeNo, ISNULL(SUM(CAST(s.stock_quantity AS DECIMAL(20, 6))), 0) AS stockQuantity FROM fact_stock_day s WHERE s.stock_date = #{stockDate} AND s.product_no = #{productNo}
GROUP BY s.store_no ), meta_base AS ( SELECT p.store_no AS storeNo, MAX(p.store_name) AS storeName, MAX(p.status_name) AS productStatus, CAST(MAX(CAST(ISNULL(p.status_no, 0) AS INT)) AS NVARCHAR(20)) AS productStatusNo FROM base_dept_products p WHERE p.product_no = #{productNo}
GROUP BY p.store_no ), detail_base AS ( SELECT sales_base.storeNo, COALESCE(meta_base.storeName, sales_base.storeName) AS storeName, ISNULL(meta_base.productStatus, N'未知') AS productStatus, ISNULL(meta_base.productStatusNo, N'0') AS productStatusNo, sales_base.saleQuantity, sales_base.sales, sales_base.gross, sales_base.saleCost, ISNULL(stock_base.stockQuantity, 0) AS stockQuantity, sales_base.activity, sales_base.firstSaleDate FROM sales_base LEFT JOIN stock_base ON stock_base.storeNo = sales_base.storeNo LEFT JOIN meta_base ON meta_base.storeNo = sales_base.storeNo WHERE 1 = 1
AND ISNULL(meta_base.productStatusNo, N'0') IN
#{item}
AND ( sales_base.storeNo LIKE CONCAT('%', #{storeKeyword}, '%') OR COALESCE(meta_base.storeName, sales_base.storeName) LIKE CONCAT('%', #{storeKeyword}, '%') )
)
